'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v==null?'—':new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(v);
const STAFF=['Administrateur','Direction / DAP'];
const TEACHER_PAGES=['Accueil','Mes vœux','Mes affectations','Mon emploi du temps','Ma charge','Mon profil'];
const ICONS={'Tableau de bord':0,'Structure':1,'Programmes':2,'Enseignants':3,'Vœux':9,'Affectations':4,'Emploi du temps':5,'Suivi':6,'Rapports':7,'Paramètres':8,'Accueil':0,'Mes vœux':9,'Mes affectations':4,'Mon emploi du temps':5,'Ma charge':7,'Mon profil':3};
function role(){return S.user.role}
function isStaff(){return STAFF.includes(role())}
function isChef(){return role()==='Chef de département'}
function isTeacher(){return role()==='Enseignant'}
function myDept(){return isChef()?S.user.department:null}
function deptName(id){return id?(S.departments[id]||'—'):'Sans département'}
function navs(){if(isTeacher())return TEACHER_PAGES;let n=['Tableau de bord','Structure','Programmes','Enseignants','Vœux','Affectations','Emploi du temps','Suivi','Rapports'];if(!isChef())n.push('Paramètres');return n}
function myNavs(){return !isTeacher()&&S.me?TEACHER_PAGES.slice(1):[]}
const paths=['M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M9 3h6v5H9z M3 16h6v5H3z M15 16h6v5h-6z M12 8v4 M6 16v-4h12v4','M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4','M4 4h16v17H4z M8 2h8v5H8z M8 12l2 2 5-5 M8 18h8','M3 5h18v16H3z M3 10h18 M7 2v6 M17 2v6 M7 14h3 M14 14h3','M3 12h4l3-8 4 16 3-8h4','M4 21V11h4v10 M10 21V6h4v15 M16 21V2h4v19','M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2','M12 21s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.6-7 10-7 10z'];
function icon(i){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[i]||paths[0]}"/></svg>`}
let S=null,page='Tableau de bord',tab='',search='',filter='',status='active',sortAsc=true,report='Programme',reportRows=[],reportHeaders=[],edit=null;
const modDefault={'Structure':'level','Programmes':'overview','Enseignants':'teacher','Vœux':'processing','Affectations':'assignment','Emploi du temps':'grid','Suivi':'session','Rapports':'reports','Paramètres':'years'};
function rec(id){return S.records.find(r=>r.id===id)}
function lab(id){return rec(id)?.label||'—'}
function list(kind,active=true){return S.records.filter(r=>r.kind===kind&&(!active||r.active))}
function currentYear(){return S.years.find(y=>y.id===S.year)}
function canWrite(){return S.user.role!=='Consultation'&&!currentYear().closed}
const CHEF_KINDS=['assignment','slot','session','wish','campaign','group','teacher','unavailable','extra'];
function canEdit(kind){if(currentYear().closed)return false;if(isStaff())return true;if(isChef())return CHEF_KINDS.includes(kind);return false}
function canEditRecord(r){if(!r)return false;if(!canEdit(r.kind))return isOwnTeacherRecord(r);if(!isChef())return true;let d=myDept();if(['assignment','slot','session','wish'].includes(r.kind))return r.context.department===d;if(r.kind==='teacher')return r.data.department===d||isOwnTeacherRecord(r);if(r.kind==='campaign')return r.data.department===d;return true}
function isOwnTeacherRecord(r){return !!S.me&&(r.id===S.me||r.data.teacher===S.me)}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function ask(message){return new Promise(resolve=>{let d=document.createElement('dialog');d.innerHTML=`<div class="dialoghead"><h2>Confirmation</h2></div><div class="dialogbody"><p>${esc(message)}</p></div><div class="dialogfoot"><button type="button" data-answer="no">Annuler</button><button type="button" class="primary" data-answer="yes">Confirmer</button></div>`;document.body.append(d);let finish=v=>{d.close();d.remove();resolve(v)};d.addEventListener('click',e=>{let b=e.target.closest('[data-answer]');if(b)finish(b.dataset.answer==='yes')});d.addEventListener('cancel',e=>{e.preventDefault();finish(false)});d.showModal()})}
let CSRF='',STATUS={app:'ges-ped',edition:'PILOTE',version:''};
async function api(path,data){let r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-CSRF-Token':S?.csrf||CSRF||''}:{},body:data?JSON.stringify(data):undefined});let v;try{v=await r.json()}catch{v={error:'Le serveur ges-ped ne répond pas correctement. Réessayez dans un instant.'}}if(!r.ok){let e=Error(v.error||'Opération impossible');e.status=r.status;if(r.status===401&&S&&!['login','password'].includes(path)){S=null;setTimeout(()=>start(e.message),0)}if(r.status===403&&S){S=null;setTimeout(forcedChange,0)}throw e}return v}
async function load(year){S=await api('bootstrap'+(year?'?year='+encodeURIComponent(year):''));render()}
function button(action,text,cls='',attrs=''){return `<button type="button" data-action="${action}" class="${cls}" ${attrs}>${text}</button>`}
function badge(value){let cls=['Brouillon','Prévue','À reprogrammer'].includes(value)?'amber':['Annulée','Dépassement'].includes(value)?'red':['Archivé','Non renseignée'].includes(value)?'gray':'';return `<span class="badge ${cls}">${esc(value)}</span>`}
function opts(items,selected='',empty='Tous'){return `<option value="">${esc(empty)}</option>`+items.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.label)}</option>`).join('')}
function head(title,sub,action=''){return `<div class="pagehead"><div><div class="eyebrow">Espace pédagogique</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function panel(title,sub,body){return `<section class="panel"><div class="panelhead"><div><h2>${title}</h2><p>${sub}</p></div></div>${body}</section>`}
function metric(title,value,note,i){return `<div class="card"><div class="metric-top">${title}<span class="metric-icon">${icon(i)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`}
function navigate(p,t){page=p;tab=t||modDefault[p]||'';search='';filter='';status='active';render()}
function navButton(n){return `<button data-nav="${n}" class="${page===n?'selected':''}">${icon(ICONS[n])}${n}</button>`}
function render(){
 if(!S)return;
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar">${brand()}<div class="nav-label">${isTeacher()?'MON ESPACE ENSEIGNANT':'GESTION PÉDAGOGIQUE'}</div><nav class="nav" aria-label="Navigation principale">${navs().map(navButton).join('')}${myNavs().length?`<div class="nav-label">MON ESPACE ENSEIGNANT</div>`+myNavs().map(navButton).join(''):''}</nav><div class="sidefoot"><b>École Nationale Supérieure<br>des Forêts — Khenchela</b><span class="badge pilot" style="margin-top:12px">Version ${esc(S.edition||'')} · ${esc(S.version)}</span></div></aside><main class="main"><header class="topbar"><div class="crumb">ges-ped <span style="margin:0 10px">/</span> ${page}</div><div class="topright"><select id="year" class="year" aria-label="Année universitaire">${S.years.map(y=>`<option value="${y.id}" ${y.id===S.year?'selected':''}>${esc(y.name)}${y.closed?' · Clôturée':''}</option>`).join('')}</select><div class="avatar">${esc(S.user.name[0].toUpperCase())}</div><div class="usertext small"><b>${esc(S.user.name)}</b><br><span class="muted">${esc(S.user.role)}${isChef()?' · '+esc(deptName(myDept())):''}</span></div>${button('feedback','Signaler un problème','subtle','title="Signaler un problème ou faire une remarque"')}${button('logout','Se déconnecter','','title="Se déconnecter"')}</div></header><div class="content"><div class="printhead"><h2>ges-ped — Gestion pédagogique ENSF · École Nationale Supérieure des Forêts — Khenchela</h2><p>${esc(currentYear().name)} · ${esc(page)} · ${esc(report)}</p></div>${currentYear().closed?'<div class="alert">Année clôturée : les données historiques sont consultables, sans modification.</div>':''}<div id="page"></div></div></main></div>`;
 if(!navs().includes(page)&&!myNavs().includes(page))page=navs()[0];
 let html=TEACHER_PAGES.includes(page)?teacherPage():page==='Tableau de bord'?(isChef()?chefDashboard():dashboard()):page==='Paramètres'?settings():page==='Rapports'?reports():modulePage();$('#page').innerHTML=html;
 if(page==='Rapports')for(let [id,visible] of Object.entries(reportVisibility())){let control=$('#'+id);if(control)control.hidden=!visible}
 if(page==='Paramètres'&&tab==='users')usersPage().catch(e=>toast(e.message));if(page==='Paramètres'&&tab==='feedback')feedbackPage().catch(e=>toast(e.message));
}
function dashboard(){let c=S.summary.counts,e=S.summary.english,remaining=S.summary.coverage.reduce((a,r)=>a+Math.max(0,r.remaining),0),unknown=false;
 let rows=list('track').map(r=>{let b=S.summary.breakdown.find(b=>b.id===r.id);return `<div class="row"><div><strong>${esc(r.label)}</strong><small>${list('level').filter(l=>l.data.track===r.id).length} niveaux · ${fmt(b?.total)} h réglementaires</small></div>${badge(`${list('subject').filter(s=>s.context.track===r.id).length} matières`)}</div>`}).join('');
 return head('Tableau de bord','Une vue d’ensemble de votre année universitaire.',button('go-programs','Consulter les programmes →','primary'))+
 `<div class="hero"><div><div class="eyebrow">ANNÉE UNIVERSITAIRE ${esc(currentYear().name)}</div><h2>Préparer les enseignements, suivre leur réalisation.</h2><p>Les programmes de référence sont en place. Complétez vos référentiels, puis affectez et planifiez les enseignements.</p>${button('go-assignments','Ouvrir les affectations','primary')}</div><svg class="hero-art" viewBox="0 0 160 140" aria-hidden="true"><path d="M20 123H148 M49 123V36 M29 78L49 44 69 78Z M20 103L49 58 78 103Z M108 123V10 M78 61L108 14 138 61Z M69 91L108 32 147 91Z M80 112L108 70 136 112Z" fill="#c4d7ba" stroke="#668660" stroke-width="1.5"/></svg></div>`+
 `<div class="cards">${metric('Enseignants actifs',fmt(c.teacher),'Annuaire de l’année',3)}${metric('Matières de référence',fmt(c.subject),`${fmt(c.activity)} activités pédagogiques`,2)}${metric('Affectations validées',fmt(list('assignment').filter(r=>r.data.state==='Validée').length),`${fmt(remaining)} h restant à répartir par public`,4)}${metric('Enseignement en anglais',fmt(e.rate)+' %',`${fmt(e.coverage)} % du volume réglementaire affecté`,6)}</div>`+
 `<div class="grid2">${panel('Votre offre de formation','Structure ENSF · référentiels administrables',`<div class="panelbody">${rows}<div class="pillrow">${badge(`${c.specialty} spécialités`)}${badge(`${c.level} niveaux / blocs`)}${badge(`${c.group} sections et groupes`)}</div></div>`)}${panel('Enseignement en anglais','Calculé sur les affectations validées, sans multiplication par groupe',`<div class="panelbody"><div class="donut" style="--amount:${e.rate||0}%"><div><b>${fmt(e.rate)} %</b><small>EN ANGLAIS</small></div></div><div class="row"><span>Heures réglementaires en anglais</span><b>${fmt(e.english)} h</b></div><div class="row"><span>Volume réglementaire total</span><b>${fmt(e.total)} h</b></div><div class="row"><span>Volume encore non affecté</span><b>${fmt(e.total-e.assigned)} h</b></div>${button('go-english','Voir le détail →')}</div>`)}
 ${panel('Points à vérifier','Anomalies conservées depuis la source fournie',`<div class="panelbody">${S.anomalies.map(a=>`<div class="row"><div><strong>${esc(a[1])} · ${esc(a[2])}</strong><small>${esc(a[4])}<br>${esc(a[5])}</small></div>${badge('À clarifier')}</div>`).join('')}<p class="muted small" style="margin-top:15px">Les départements, effectifs, salles et dates de semestre sont à compléter. La langue d’enseignement est désormais choisie dans chaque affectation. Les PDF signés des arrêtés ne sont pas inclus dans le dossier.</p></div>`)}
 ${panel('Commencer votre année','Un parcours simple, à votre rythme',`<div class="panelbody">${[['Structure','semester','Compléter la structure','Départements, dates, effectifs et salles'],['Enseignants','teacher','Constituer l’annuaire','Grades, statuts et décisions de charge'],['Vœux','campaign','Ouvrir une campagne de vœux','Les enseignants expriment leurs souhaits'],['Affectations','remaining','Affecter les enseignements','Depuis les vœux ou manuellement']].map((s,i)=>`<div class="step"><span>${i+1}</span><button data-nav="${s[0]}" data-tab="${s[1]}">${s[2]}<small>${s[3]}</small></button></div>`).join('')}</div>`)}</div>`;
}
function moduleTabs(){let tabs=Object.entries(S.schema).filter(([k,v])=>v.module===page).map(([k,v])=>[k,v.title]);if(page==='Programmes')tabs.unshift(['overview','Vue du programme']);if(page==='Emploi du temps')tabs.unshift(['grid','Grille hebdomadaire']);if(page==='Affectations'){tabs.splice(1,0,['remaining','Activités restant à affecter']);tabs.push(['coverage','Couverture par public'],['loads','Charges enseignants (ENSF)'])}if(page==='Vœux'){tabs.unshift(['processing','Traitement des vœux']);tabs.push(['nowish','Sans réponse / sans candidat'])}return tabs}
function modulePage(){let tabs=moduleTabs();if(!tabs.some(x=>x[0]===tab))tab=tabs[0][0];let title=tabs.find(t=>t[0]===tab)[1];
 return head(page,{'Structure':'Organisez vos formations, vos groupes et vos espaces.','Programmes':'Du semestre aux activités : un programme lisible et traçable.','Enseignants':'Un enseignant = une seule fiche ENSF, quel que soit le nombre de départements où il intervient.','Vœux':'Campagnes, vœux des enseignants et arbitrage par le chef du département de la matière.','Affectations':'Affectez depuis les vœux ou manuellement, puis validez.','Emploi du temps':'Planifiez à partir des affectations validées.','Suivi':'Renseignez les séances réalisées et organisez les rattrapages.'}[page],canEdit(tab)&&S.schema[tab]&&!(tab==='wish'&&!isStaff())?button('add',tab==='assignment'?'+ Nouvelle affectation manuelle':'+ Ajouter','primary'):'')+
 `<div class="tabs">${tabs.map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div>`+
 (tab==='overview'?programView():tab==='grid'?timetable():tab==='coverage'?coverageView():tab==='loads'?loadsView():tab==='remaining'?remainingView():tab==='processing'?processingView():tab==='nowish'?noWishView():entityTable(tab));
}
const columns={teacher:['last','first','grade','department','status','load','english_level'],activity:['subject','type','hours','category'],assignment:['activity','teacher','group','hours','language','state','wish'],campaign:['name','period','department','open','deadline','status'],wish:['activity','teacher','priority','language','state','decision_date'],subject:['name','ue','coefficient','credits','source_volume'],semester:['name','level','period','start','weeks'],session:['date','start','assignment','room','duration','state','actual'],slot:['day','start','assignment','room','duration','weeks'],level:['name','track','specialty'],group:['name','level','type','parent','size'],rule:['name','normal','half','weeks','duration','source'],extra:['name','teacher','type','hours','equivalent','decision','state']};
function filtered(kind){let rr=list(kind,false).filter(r=>status==='all'||(status==='active'?r.active:!r.active));if(filter)rr=rr.filter(r=>r.context.semester===filter||r.context.department===filter||r.context.teacher===filter||r.data.level===filter);if(search)rr=rr.filter(r=>[r.label,...Object.values(r.data).map(v=>rec(v)?.label||String(v??''))].join(' ').toLocaleLowerCase('fr').includes(search.toLocaleLowerCase('fr')));return rr.sort((a,b)=>(sortAsc?1:-1)*a.label.localeCompare(b.label,'fr',{numeric:true}))}
function controls(kind,extra=''){let sf=['subject','ue','activity','assignment','session','slot','wish'].includes(kind)?list('semester'):kind==='teacher'?list('department'):kind==='group'?list('level'):[];return `<div class="toolbar"><input id="search" class="search" placeholder="Rechercher…" aria-label="Rechercher" value="${esc(search)}">${sf.length?`<select id="filter" aria-label="Filtrer">${opts(sf,filter,'Tous les '+(kind==='teacher'?'départements':kind==='group'?'niveaux':'semestres'))}</select>`:''}<select id="status" aria-label="État"><option value="active" ${status==='active'?'selected':''}>Actifs</option><option value="all" ${status==='all'?'selected':''}>Tous les états</option><option value="archived" ${status==='archived'?'selected':''}>Archivés</option></select>${button('sort','↕ Trier')}${extra}${button('export','Excel')}${button('print','PDF / Imprimer')}</div>`}
function valueCell(r,f){let v=r.data[f.key];if(f.key==='wish')return v?badge('Issue d’un vœu'):'Manuelle';if(f.key==='status'&&r.kind==='campaign')return badge(v);if(f.key==='department'&&r.kind==='campaign'&&!v)return 'Tous';if(f.type==='ref')return esc(v?lab(v):'Non renseignée');if(f.type==='number')return fmt(v);if(f.key==='state')return badge(sessionState(r));return esc(v??'—')}
function sessionState(r){if(r.kind!=='session')return r.data.state;let replacements=list('session').filter(s=>s.data.replaces===r.id),actual=replacements.reduce((a,s)=>a+s.data.actual,0);if(['Annulée','À reprogrammer','Partiellement réalisée'].includes(r.data.state)&&actual>=r.data.duration-r.data.actual&&actual>0)return 'Rattrapée';return r.data.state}
function entityTable(kind){let sch=S.schema[kind],fields=(columns[kind]||sch.fields.slice(0,6).map(f=>f.key)).map(k=>sch.fields.find(f=>f.key===k)),rr=filtered(kind);
 const importable=['teacher','room','department','cycle','track','specialty','level','semester','group','ue','subject','activity','language','grade','status','roomtype','uetype'].includes(kind);
 let hint=kind==='activity'?'<div class="alert">Le programme officiel reste en français : la langue réellement utilisée est choisie dans chaque affectation. Le bloc PFE conserve les volumes sources, sans équivalence de charge automatique.</div>':kind==='assignment'?`<div class="alert">${isChef()?'Vous affectez les enseignements de votre département à tout enseignant ENSF, quel que soit son rattachement administratif. ':''}Les brouillons réservent le volume ; seules les affectations validées alimentent la charge globale ENSF et l’emploi du temps.</div>`:kind==='teacher'?'<div class="alert">Le département administratif est facultatif et n’a aucun effet sur les affectations. La charge est toujours calculée sur l’ensemble des affectations ENSF.</div>':kind==='campaign'?'<div class="alert">Pendant une campagne ouverte, chaque enseignant formule ses vœux depuis son espace, pour les matières de n’importe quel département. Les vœux ne sont pas limités par la charge.</div>':kind==='session'?'<p class="muted small">Les séances sont générées après validation de la grille. Pour un rattrapage, ouvrez une séance annulée ou partielle puis choisissez « Programmer un rattrapage ».</p>':'';
 return hint+controls(kind,importable&&isStaff()&&canWrite()?button('import','Importer'):'')+`<div class="panel"><div class="tablewrap"><table><thead><tr>${fields.map(f=>`<th>${esc(f.label)}</th>`).join('')}<th>État</th><th class="noprint">Actions</th></tr></thead><tbody>${rr.map(r=>`<tr>${fields.map(f=>`<td>${valueCell(r,f)}</td>`).join('')}<td>${badge(r.active?'Actif':'Archivé')}</td><td class="noprint"><div class="actions">${button('edit','Ouvrir','',`data-id="${r.id}"`)}${kind==='assignment'&&canEditRecord(r)?button('duplicate','Dupliquer','',`data-id="${r.id}"`):''}${kind==='wish'?button('history','Historique','',`data-id="${r.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div>${!rr.length?`<div class="empty"><div class="empty-symbol">＋</div><h2>${search||filter?'Aucun résultat':'Votre espace est prêt'}</h2><p>${kind==='teacher'?'Ajoutez votre premier enseignant ou importez votre annuaire. Aucune affectation réelle n’a été préchargée.':'Ajoutez une fiche pour commencer, ou ajustez vos filtres.'}</p>${canEdit(kind)&&kind!=='wish'?button('add','+ Ajouter','primary'):''}</div>`:''}<div class="tablefoot"><span>${rr.length} résultat${rr.length>1?'s':''}</span><span>${sch.title} · ${esc(currentYear().name)}</span></div></div>`;
}
function programView(){let semesters=list('semester');if(!filter)filter=semesters[0]?.id||'';let subjects=list('subject').filter(s=>s.context.semester===filter);let acts=list('activity').filter(a=>a.context.semester===filter);let total=acts.reduce((n,a)=>n+a.data.hours,0);
 return `<div class="toolbar"><select id="filter" aria-label="Semestre" style="max-width:650px">${opts(semesters,filter,'Choisir un semestre')}</select><span class="spacer"></span>${button('print','PDF / Imprimer')}${button('program-report','Rapport Excel')}</div><div class="cards">${metric('Matières',subjects.length,'Dans ce semestre',2)}${metric('Volume des activités',fmt(total)+' h','Somme des lignes sources',6)}${metric('Crédits renseignés',fmt(subjects.reduce((s,r)=>s+(r.data.credits||0),0)),'Les valeurs absentes restent à confirmer',2)}${metric('Heures en anglais',fmt(acts.reduce((n,a)=>n+(S.summary.activityStats?.[a.id]?.english||0),0))+' h','Selon les affectations validées',6)}</div>`+
 list('ue').filter(u=>u.data.semester===filter).map(u=>panel(esc(u.data.code||u.data.name),esc(u.data.name),subjects.filter(s=>s.data.ue===u.id).map(s=>`<div class="activity-card"><div class="prog-head"><div><h3>${esc(s.data.name)}</h3><span class="muted small">${esc(deptName(s.context.department))} · ${esc(s.data.code||'Sans code')} · Coeff. ${fmt(s.data.coefficient)} · ${fmt(s.data.credits)} crédits · VHS imprimé ${fmt(s.data.source_volume)} h</span></div>${button('edit','Ouvrir','noprint',`data-id="${s.id}"`)}</div><div class="activity-details">${acts.filter(a=>a.data.subject===s.id).map(a=>`<button class="badge" data-action="edit" data-id="${a.id}">${esc(rec(a.data.type)?.data.name)} · ${fmt(a.data.hours)} h${S.summary.activityStats?.[a.id]?.english?' · '+fmt(S.summary.activityStats[a.id].english)+' h en anglais':''}</button>`).join('')}</div><p class="muted small" style="margin:10px 0 0">${esc(s.data.source||'')} ${s.data.note?' · '+esc(s.data.note):''}</p></div>`).join(''))).join('');
}
