function settings(){let tabs=[['years','Années universitaires'],...Object.entries(S.schema).filter(([k,v])=>v.module==='Paramètres').map(([k,v])=>[k,v.title]),['users','Comptes utilisateurs'],['feedback','Retours pilotes'],['backup','Sauvegarde'],['sources','Sources et décisions'],['audit','Historique']];if(S.user.role!=='Administrateur')tabs=tabs.filter(t=>t[0]!=='users');let content='';
 if(tab==='years'){content=panel('Historique des années','La duplication copie les référentiels et l’annuaire, sans affectations ni séances.',`<div class="panelbody">${S.years.map(y=>`<div class="row"><div><strong>${esc(y.name)}</strong><small>${y.closed?'Clôturée · historique protégé':'Ouverte'}</small></div><div class="actions">${button('switch-year','Consulter','',`data-id="${y.id}"`)}${S.user.role==='Administrateur'?button('duplicate-year','Créer l’année suivante','',`data-id="${y.id}"`):''}${!y.closed&&S.user.role==='Administrateur'?button('close-year','Clôturer','danger',`data-id="${y.id}"`):''}</div></div>`).join('')}</div>`)}
 else if(tab==='backup'){content=panel('Sauvegarder votre travail','Les données restent sur votre ordinateur. Conservez une copie sur un support externe.',`<div class="panelbody"><p>La sauvegarde contient les années, les référentiels, les affectations, les séances et le journal. Les comptes et mots de passe restent sur ce PC lors d’une restauration.</p>${button('backup','Télécharger une sauvegarde','primary')}<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h2>Restaurer une sauvegarde</h2><p class="muted">Un aperçu indique la date et le volume des données avant confirmation. Une copie de sécurité est créée automatiquement avant le remplacement.</p>${button('restore','Choisir une sauvegarde…')}</div>`)}
 else if(tab==='users'){content='<div id="users-page"><p class="muted">Chargement des comptes…</p></div>'}
 else if(tab==='feedback'){content='<div id="feedback-page"><p class="muted">Chargement des retours…</p></div>'}
 else if(tab==='sources'){content=`<div class="alert">Les programmes proviennent du classeur fourni ; les arrêtés signés ne sont pas présents. Aucun rattachement de département ni langue d’enseignement n’a été inventé. Les blocs complémentaires sont séparés et leur rattachement reste à confirmer.</div>`+dataTable(['Formation','Bloc','Constat','Total source','Traitement'],S.anomalies.map(a=>[a[1],a[2],a[4],a[5],a[6]]))+dataTable(['Référence','Date','Règle retenue','Statut'],S.sources.map(a=>[a[1],a[2],a[5],a[7]]))}
 else if(tab==='audit'){content=`<div class="panel"><div class="panelbody"><p>Chaque modification conserve l’auteur, la date et les valeurs avant / après.</p>${button('audit','Charger l’historique','primary')}<div id="audit-content"></div></div></div>`}
 else content=(tab==='rule'?'<div class="alert">Chaque ajout crée une nouvelle version des règles. Les versions antérieures sont conservées. Les coefficients Cours / TD / TP se trouvent dans Types d’activités.</div>':'')+entityTable(tab);
 return head('Paramètres','Vos référentiels, vos règles et vos données.',S.schema[tab]&&canWrite()?button('add',tab==='rule'?'+ Nouvelle version':'+ Ajouter','primary'):'')+`<div class="tabs">${tabs.map(([k,v])=>`<button data-tab="${k}" class="${tab===k?'selected':''}">${v}</button>`).join('')}</div>`+content;
}
function openDialog(title,body,footer=''){let d=$('#dialog');d.innerHTML=`<div class="dialoghead"><h2>${esc(title)}</h2>${button('close','×','','aria-label="Fermer"')}</div><div class="dialogbody"><div class="form-error" id="form-error" role="alert"></div>${body}</div>${footer?`<div class="dialogfoot">${footer}</div>`:''}`;d.showModal()}
function candidates(kind,key,data,id){let f=S.schema[kind].fields.find(f=>f.key===key),rr=list(f.ref,false).filter(r=>r.active||r.id===data[key]);if(kind==='assignment'&&key==='group'&&data.activity){let act=rec(data.activity),typ=rec(act.data.type);rr=rr.filter(r=>r.data.level===act.context.level&&(typ.data.target==='Libre'||r.data.type===typ.data.target||(typ.data.target==='Groupe'&&r.data.type==='Sous-groupe')))}if(kind==='assignment'&&key==='activity'&&isChef())rr=rr.filter(r=>r.context.department===myDept()&&r.data.category!=='PFE');if(kind==='assignment'&&key==='wish')rr=rr.filter(r=>['Acceptée','Acceptée partiellement'].includes(r.data.state)&&(!data.activity||r.data.activity===data.activity)&&(!data.teacher||r.data.teacher===data.teacher));if(kind==='wish'&&key==='language')rr=rr.filter(r=>['fr','en'].includes(r.data.code));if(kind==='campaign'&&key==='department'&&isChef())rr=rr.filter(r=>r.id===myDept());if(kind==='slot'&&key==='assignment')rr=rr.filter(r=>r.data.state==='Validée'&&(!isChef()||r.context.department===myDept()));if(kind==='session'&&key==='assignment')rr=rr.filter(r=>r.data.state==='Validée');if(key==='parent')rr=rr.filter(r=>r.id!==id);return rr}
function editForm(kind,id=null,preset={}){let r=id?rec(id):null,d=r?{...r.data}:{...preset};edit={kind,id,revision:r?.revision,active:r?.active??1};let schema=S.schema[kind];
 if(kind==='assignment'&&!id){d.state=d.state||'Brouillon';if(d.activity)d.hours=d.hours||rec(d.activity).data.hours}
 if(kind==='campaign'&&!id){d.status='Préparation';d.period='1';if(isChef())d.department=myDept()}
 if(kind==='teacher'&&!id&&isChef())d.department=myDept();
 if(kind==='slot'&&!id){let rule=list('rule')[0]?.data;d.duration=d.duration||rule?.duration||1.5;d.weeks=d.weeks||'toutes';d.start=d.start||S.timeslots[0][0];d.day=d.day||S.days[0]}
 if(kind==='session'&&!id){d.state='Prévue';d.actual=0;d.duration=d.duration||1.5;d.start=d.start||'08:00'}
 if(kind==='teacher'&&!id){d.load='Normale';d.status=list('status').find(s=>s.data.name==='Permanent')?.id}
 if(kind==='semester'&&!id){d.weeks=list('rule')[0]?.data.weeks||14;d.period='1'}
 if(kind==='activity'&&!id)d.category='Réglementaire';
 let fields=schema.fields.filter(f=>!f.auto).map(f=>{let val=d[f.key]??'',input='';if(f.type==='ref'){let rr=candidates(kind,f.key,d,id);input=`<input class="refsearch" data-search-ref="${f.key}" aria-label="Rechercher ${esc(f.label)}" placeholder="Rechercher dans la liste…"><select aria-label="${esc(f.label)}" name="${f.key}" ${f.required?'required':''}>${opts(rr,val,'Choisir…')}</select>`}else if(f.type==='select')input=`<select name="${f.key}">${f.options.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else if(f.type==='textarea')input=`<textarea name="${f.key}">${esc(val)}</textarea>`;else if(kind==='slot'&&f.key==='start')input=`<select name="start">${S.timeslots.map(([a,b])=>`<option value="${a}" ${a===val?'selected':''}>${a} – ${b}</option>`).join('')}</select>`;else input=`<input name="${f.key}" type="${f.type==='number'?'number':f.type==='date'?'date':f.type==='time'?'time':'text'}" value="${esc(val)}" ${f.required?'required':''} ${f.type==='number'?`step="any" min="${f.min??0}" max="${f.max??1000000000}"`:''}>`;return `<label class="field ${f.type==='textarea'?'wide':''}">${esc(f.label)}${f.required?' *':''}${input}</label>`}).join('');
 let extra=kind==='assignment'?'<div id="assignment-hint" class="alert" style="margin-top:15px">Sélectionnez l’activité, puis le public et l’enseignant.</div><div id="teacher-hint"></div>':kind==='wish'&&r?`<p class="muted small">Déposé le ${esc(r.data.submitted||'—')} · modifié le ${esc(r.data.updated||'—')} · décision le ${esc(r.data.decision_date||'—')} par ${esc(r.data.decided_by||'—')}</p>`:'';
 let linked=r&&S.records.some(x=>Object.values(x.data).includes(r.id));
 let writable=r?canEditRecord(r):canEdit(kind);
 let foot=writable?`${r&&kind!=='rule'?button('archive',r.active?'Archiver':'Réactiver','','data-edit="1"'):''}${r&&!linked&&kind!=='rule'?button('delete','Supprimer','danger'):''}${r&&kind==='session'&&['Annulée','À reprogrammer','Partiellement réalisée'].includes(r.data.state)?button('makeup','Programmer un rattrapage'):''}<span class="spacer"></span>${button('close','Annuler')}${button('save','Enregistrer','primary')}`:button('close','Fermer');
 openDialog((id?'Fiche · ':'Ajouter · ')+schema.title,`<form id="editor"><div class="formgrid">${fields}</div>${extra}</form>${r?`<p class="muted small" style="margin-top:16px">Version ${r.revision} · ${r.active?'Active':'Archivée'} · ${esc(currentYear().name)}</p>`:''}`,foot);
 if(!writable)$$('#editor input,#editor select,#editor textarea').forEach(e=>e.disabled=true);
 if(kind==='assignment')assignmentHint();
}
function formData(){return Object.fromEntries(new FormData($('#editor')).entries())}
function assignmentHint(){if(!$('#editor')||edit.kind!=='assignment')return;let d=formData(),act=rec(d.activity),g=d.group;$('#teacher-hint').innerHTML=d.teacher?teacherCard(d.teacher,act):'';if(!act)return;let used=list('assignment').filter(a=>a.id!==edit.id&&a.data.activity===d.activity&&a.data.group===g).reduce((n,a)=>n+a.data.hours,0);$('#assignment-hint').innerHTML=`<b>${esc(lab(act.context.level))}</b> · ${esc(lab(act.context.semester))} · ${esc(deptName(act.context.department))}<br>Volume réglementaire par public : <b>${fmt(act.data.hours)} h</b> · Déjà réservé : <b>${fmt(used)} h</b> · Disponible : <b>${fmt(act.data.hours-used)} h</b><br>La langue réellement utilisée est choisie ici (programme officiel en français).`}
function periodOf(actId){return rec(rec(actId)?.context.semester)?.data.period}
function factorOf(actId){return rec(rec(actId)?.data.type)?.data.factor||0}
function teacherCard(tid,act){let t=rec(tid);if(!t)return '';let per=act?periodOf(act.id):null,loads=S.summary.loads.filter(l=>l.teacher===tid&&(!per||l.period===per)),busy=(S.summary.busy||[]).filter(b=>b.teacher===tid&&(!per||b.period===per));
 let rows=loads.map(l=>`<div class="row"><span>Période ${l.period} · charge globale ENSF</span><b>${fmt(l.assigned)} h Eq.C / cible ${fmt(l.target)} h · reste ${fmt(l.target==null?null:Math.max(0,l.target-l.assigned-l.extra))} h</b></div><div class="row"><span>Affectations existantes</span><b>${esc(deptSplit(l.depts))}</b></div>`).join('');
 let add=act?(Number($('#editor input[name="hours"]')?.value)||0)*factorOf(act.id):0,l=loads[0],over=l&&l.target!=null&&l.assigned+l.extra+add>l.target+.01;
 return `<div class="panel" style="margin-top:12px"><div class="panelbody"><h3>${esc(t.label)} <span class="muted small">· Dépt administratif : ${esc(deptName(t.data.department))}</span></h3>${rows}<div class="row"><span>Niveau d’anglais</span><b>${esc(t.data.english_level||'Non renseigné')} · ${esc(t.data.english_ok||'Non déclaré')}</b></div><div class="row"><span>Créneaux déjà occupés (tous départements)</span><b>${busy.length?busy.map(b=>esc(b.day+' '+b.start+' ('+fmt(b.duration)+' h) · '+deptName(b.department))).join('<br>'):'Aucun'}</b></div><div class="row"><span>Conflits horaires éventuels</span><b>${busy.length?'À vérifier lors du placement (contrôle automatique)':'Non'}</b></div>${over?`<p class="form-error" style="display:block">Cette affectation porterait la charge globale ENSF au-delà de la cible (${fmt(l.assigned+l.extra+add)} h Eq.C).</p>`:''}</div></div>`}
async function saveEditor(active){let form=$('#editor');if(!form.reportValidity())return;let data=formData();let r=await api('save',{year:S.year,...edit,active:active??edit.active,data});$('#dialog').close();await load(S.year);toast(r.warning||'Fiche enregistrée.');return r}
async function downloadReport(){let r=await fetch('/api/report-export',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':S.csrf},body:JSON.stringify({headers:reportHeaders,rows:reportRows})});if(!r.ok)throw Error((await r.json()).error);download(await r.blob(),'ges-ped_'+report.replaceAll(' ','_')+'.xlsx')}
function download(blob,name){let u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function chooseFile(accept,callback){let i=document.createElement('input');i.type='file';i.accept=accept;i.addEventListener('change',async()=>{try{if(i.files[0])await callback(i.files[0])}catch(e){toast(e.message)}});i.click()}
async function importFile(){let kind=tab;chooseFile('.xlsx',async file=>{let buf=new Uint8Array(await file.arrayBuffer()),str='';for(let b of buf)str+=String.fromCharCode(b);let p=await api('import-preview',{year:S.year,kind,content:btoa(str)});let fields=S.schema[kind].fields;openDialog('Aperçu de l’import',`<p>${p.rows.length} lignes valides · ${p.errors.length} erreurs. L’import ajoute de nouvelles fiches.</p>${p.errors.length?dataTable(['Ligne','Erreur'],p.errors.map(e=>[e.row,e.error])):''}${dataTable(fields.slice(0,5).map(f=>f.label),p.rows.slice(0,30).map(r=>fields.slice(0,5).map(f=>f.type==='ref'?lab(r[f.key]):r[f.key])))}<p class="small muted">Aperçu limité à 30 lignes. Les en-têtes attendus sont ceux de l’export Excel du même référentiel.</p>`,button('close','Annuler')+button('confirm-import',`Importer ${p.rows.length} fiches`,'primary',`data-token="${p.token}" ${p.errors.length?'disabled':''}`))})}
/* ===== Version 1.1 : vœux, espaces chef de département et enseignant ===== */
const WISH_BADGE={'En attente':'amber','Acceptée':'','Acceptée partiellement':'','Refusée':'red','Retirée':'gray'};
function wbadge(v){return `<span class="badge ${WISH_BADGE[v]??''}">${esc(v)}</span>`}
function scopeDept(r){let d=myDept();return !d||r.context.department===d}
function liveWishes(){return list('wish').filter(w=>w.data.state!=='Retirée')}
function deptWishes(){return liveWishes().filter(scopeDept)}
function actLabel(a){let x=rec(a);return x?`${rec(x.data.subject)?.data.name} · ${rec(x.data.type)?.data.name}`:'—'}
function campaignsFor(){return list('campaign').filter(c=>c.data.status!=='Préparation'&&(!myDept()||!c.data.department||c.data.department===myDept()))}
function englishAgg(acts){let st=S.summary.activityStats||{},t=0,e=0,c=0;for(let a of acts){let x=st[a.id];if(!x)continue;t+=a.data.hours;e+=x.english;c+=x.assigned}return {total:t,english:e,assigned:c,rate:t?e/t*100:null,coverage:t?c/t*100:null}}
function regActs(){return list('activity').filter(a=>a.data.category==='Réglementaire')}
function remainingRows(){let cov=S.summary.coverage,wishes=liveWishes();
 return list('activity').filter(a=>a.data.category!=='PFE'&&scopeDept(a)).map(a=>{let c=cov.filter(x=>x.activity===a.id),required=c.reduce((n,x)=>n+x.required,0)||a.data.hours,validated=c.reduce((n,x)=>n+x.assigned,0),draft=list('assignment').filter(x=>x.data.activity===a.id&&x.data.state==='Brouillon').reduce((n,x)=>n+x.data.hours,0),w=wishes.filter(x=>x.data.activity===a.id),pending=w.filter(x=>x.data.state==='En attente').length;
  let state=validated<=.001?'Non affecté':validated>required+.01?'Dépassement':validated<required-.01?'Partiellement affecté':'Affecté';
  return {a,publics:c.length||1,required,validated,draft,wishes:w.length,pending,state,arbitration:pending>0&&state!=='Affecté'}})}
function stateBadge(r){let cls=r.state==='Non affecté'?'red':r.state==='Partiellement affecté'?'amber':r.state==='Dépassement'?'red':'';return `<span class="badge ${cls}">${esc(r.state)}</span>${r.arbitration?' '+badge('En arbitrage'):''}`}
let remState='open',remLevel='';
function remainingView(){let rr=remainingRows().filter(r=>(!filter||r.a.context.semester===filter)&&(!remLevel||r.a.context.level===remLevel)&&(remState==='all'||(remState==='open'?['Non affecté','Partiellement affecté','Dépassement'].includes(r.state):r.state===remState))&&(!search||r.a.label.toLowerCase().includes(search.toLowerCase())));
 return `<div class="alert">Volume par public (section / groupe). Un enseignement peut être partagé entre plusieurs enseignants, venant de n’importe quel département ; la somme est contrôlée automatiquement.</div><div class="toolbar"><input id="search" class="search" placeholder="Rechercher une matière…" value="${esc(search)}"><select id="remLevel">${opts(list('level'),remLevel,'Tous les niveaux')}</select><select id="filter">${opts(list('semester'),filter,'Tous les semestres')}</select><select id="remState">${[['open','À traiter (non / partiellement affecté, dépassement)'],['all','Tous les états'],['Non affecté','Non affecté'],['Partiellement affecté','Partiellement affecté'],['Affecté','Affecté'],['Dépassement','Dépassement']].map(([v,t])=>`<option value="${v}" ${remState===v?'selected':''}>${t}</option>`).join('')}</select>${button('print','PDF / Imprimer')}</div>`+
 `<div class="panel"><div class="tablewrap"><table><thead><tr><th>Niveau</th><th>Matière</th><th>Activité</th><th>Volume / public</th><th>Publics</th><th>Affecté (validé)</th><th>Reste</th><th>Brouillon</th><th>Candidats</th><th>État</th><th class="noprint"></th></tr></thead><tbody>${rr.map(r=>`<tr><td>${esc(lab(r.a.context.level))}<small>${esc(rec(r.a.context.semester)?.data.name)} · ${esc(deptName(r.a.context.department))}</small></td><td>${esc(rec(r.a.data.subject)?.data.name)}</td><td>${esc(lab(r.a.data.type))}</td><td>${fmt(r.a.data.hours)} h</td><td>${r.publics}</td><td>${fmt(r.validated)} / ${fmt(r.required)} h</td><td>${fmt(Math.max(0,r.required-r.validated))} h</td><td>${fmt(r.draft)} h</td><td>${r.wishes}${r.pending?` <small>${r.pending} en attente</small>`:''}</td><td>${stateBadge(r)}</td><td class="noprint"><div class="actions">${r.wishes?button('see-wishes','Vœux','',`data-id="${r.a.id}"`):''}${canEdit('assignment')&&!currentYear().closed?button('assign-activity','Affecter','',`data-id="${r.a.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div>${rr.length?'':'<div class="empty"><h2>Rien à afficher</h2><p>Aucune activité ne correspond à ces filtres.</p></div>'}<div class="tablefoot">${rr.length} activités</div></div>`}
let wCampaign='',wState='',wTeacher='',wType='',wLevel='',wActivity='';
function wishAlerts(w){let t=rec(w.data.teacher),per=periodOf(w.data.activity),l=S.summary.loads.find(x=>x.teacher===w.data.teacher&&x.period===per),out=[];
 if(list('assignment').some(a=>a.data.teacher===w.data.teacher&&a.data.activity===w.data.activity))out.push('Déjà affecté à cette activité');
 let add=(rec(w.data.activity)?.data.hours||0)*factorOf(w.data.activity);if(!out.length&&l&&l.target!=null&&l.assigned+l.extra+add>l.target+.01)out.push('Dépassement potentiel de la charge');
 if(rec(w.data.language)?.data.code==='en'&&t?.data.english_ok==='Non')out.push('N’a pas déclaré pouvoir enseigner en anglais');
 let busy=(S.summary.busy||[]).filter(b=>b.teacher===w.data.teacher&&b.period===per);if(busy.length)out.push(busy.length+' créneau(x) occupé(s)');
 if(t&&!t.active)out.push('Enseignant archivé');return out}
function processingView(){let camps=campaignsFor(),ws=list('wish').filter(scopeDept).filter(w=>(!wCampaign||w.data.campaign===wCampaign)&&(wState?w.data.state===wState:w.data.state!=='Retirée')&&(!wTeacher||w.data.teacher===wTeacher)&&(!wType||rec(w.data.activity)?.data.type===wType)&&(!wLevel||w.context.level===wLevel)&&(!filter||w.context.semester===filter)&&(!wActivity||w.data.activity===wActivity)&&(!search||w.label.toLowerCase().includes(search.toLowerCase())));
 let groups={};for(let w of ws)(groups[w.data.activity]=groups[w.data.activity]||[]).push(w);
 let rem=Object.fromEntries(remainingRows().map(r=>[r.a.id,r]));
 let body=Object.entries(groups).sort((a,b)=>lab(a[0]).localeCompare(lab(b[0]),'fr')).map(([aid,items])=>{let a=rec(aid),r=rem[aid],live=items.filter(w=>w.data.state!=='Retirée');items.sort((x,y)=>x.data.priority-y.data.priority);
  return `<section class="panel"><div class="panelhead"><div><h2>${esc(actLabel(aid))} · ${fmt(a?.data.hours)} h</h2><p>${esc(lab(a?.context.level))} · ${esc(rec(a?.context.semester)?.data.name)} · ${esc(deptName(a?.context.department))} · ${live.length} candidat${live.length>1?'s':''}${r?' · affecté '+fmt(r.validated)+' / '+fmt(r.required)+' h':''}</p></div>${r?stateBadge(r):''}</div><div class="tablewrap"><table><thead><tr><th>Enseignant</th><th>Choix · langue souhaitée</th><th>Anglais</th><th>Charge ENSF · reste</th><th>Affectations ENSF</th><th>Alertes</th><th>Décision</th><th class="noprint">Actions</th></tr></thead><tbody>${items.map(w=>{let t=rec(w.data.teacher),l=S.summary.loads.find(x=>x.teacher===w.data.teacher&&x.period===periodOf(aid)),al=wishAlerts(w),mine=canEditRecord(w)&&!currentYear().closed,linked=list('assignment').filter(x=>x.data.wish===w.id);
   return `<tr><td>${esc(t?.label||'—')}<small>Dépt adm. : ${esc(deptName(t?.data.department))}</small>${w.data.note?`<small>« ${esc(w.data.note)} »</small>`:''}</td><td>Choix ${fmt(w.data.priority)}<small>${esc(lab(w.data.language))}</small></td><td>${esc(t?.data.english_level||'Non renseigné')}<small>${esc(t?.data.english_ok||'')}</small></td><td>${l?fmt(l.assigned)+' / '+fmt(l.target)+' h':'—'}<small>${l&&l.target!=null?'reste '+fmt(Math.max(0,l.target-l.assigned-l.extra))+' h':''}</small></td><td>${esc(l?deptSplit(l.depts):'—')}</td><td>${al.length?al.map(x=>`<small>⚠ ${esc(x)}</small>`).join(''):'—'}</td><td>${wbadge(w.data.state)}${w.data.decision_note?`<small>${esc(w.data.decision_note)}</small>`:''}${linked.length?'<small>Affectation créée</small>':''}</td><td class="noprint"><div class="actions" style="flex-direction:column;align-items:stretch;min-width:120px">${mine&&w.data.state!=='Retirée'?[['Acceptée','Accepter',''],['Acceptée partiellement','Partiel',''],['Refusée','Refuser','danger']].filter(([st])=>st!==w.data.state).map(([st,t,c])=>button('decide',t,c,`data-id="${w.id}" data-state="${st}"`)).join(''):''}${mine&&['Acceptée','Acceptée partiellement'].includes(w.data.state)?button('wish-assign','Créer l’affectation','primary',`data-id="${w.id}"`):''}${button('history','Historique','',`data-id="${w.id}"`)}</div></td></tr>`}).join('')}</tbody></table></div></section>`}).join('');
 return `<div class="alert">Aide à la décision uniquement : aucun titulaire n’est choisi automatiquement. La décision appartient au chef du département de la matière. Les vœux refusés restent historisés.</div><div class="toolbar"><input id="search" class="search" placeholder="Rechercher matière ou enseignant…" value="${esc(search)}"><select id="wCampaign">${opts(camps,wCampaign,'Toutes les campagnes')}</select><select id="wLevel">${opts(list('level'),wLevel,'Tous les niveaux')}</select><select id="filter">${opts(list('semester'),filter,'Tous les semestres')}</select><select id="wType">${opts(list('activitytype'),wType,'Toutes activités')}</select><select id="wTeacher">${opts(list('teacher'),wTeacher,'Tous les enseignants')}</select><select id="wState"><option value="">À traiter et traités</option>${S.schema.wish.fields.find(f=>f.key==='state').options.map(o=>`<option ${o===wState?'selected':''}>${o}</option>`).join('')}</select>${wActivity?button('clear-wactivity','× '+esc(actLabel(wActivity))):''}${button('print','PDF / Imprimer')}</div>`+(body||'<div class="panel"><div class="empty"><h2>Aucun vœu pour cette sélection</h2><p>Les vœux apparaissent ici dès que les enseignants les déposent pendant une campagne ouverte. Vous pouvez toujours affecter manuellement.</p></div></div>')}
function concernedTeachers(){let d=myDept(),ids=new Set();for(let a of list('assignment'))if(!d||a.context.department===d)ids.add(a.data.teacher);for(let w of deptWishes())ids.add(w.data.teacher);if(d)for(let t of list('teacher'))if(t.data.department===d)ids.add(t.id);return [...ids].map(rec).filter(Boolean)}
function noWishView(){let camps=campaignsFor(),periods=new Set(camps.map(c=>c.data.period)),wishes=deptWishes(),answered=new Set(wishes.map(w=>w.data.teacher));
 let silent=concernedTeachers().filter(t=>t.active&&!answered.has(t.id));
 let nocand=list('activity').filter(a=>scopeDept(a)&&['Réglementaire','Formation complémentaire'].includes(a.data.category)&&periods.has(rec(a.context.semester)?.data.period)&&!wishes.some(w=>w.data.activity===a.id));
 let multi=Object.entries(wishes.reduce((m,w)=>(m[w.data.activity]=(m[w.data.activity]||0)+1,m),{})).filter(([k,v])=>v>1);
 return (camps.length?'':'<div class="alert">Aucune campagne ouverte ou clôturée : créez une campagne dans l’onglet « Campagnes de vœux ».</div>')+
 panel('Enseignants n’ayant pas répondu',`${silent.length} enseignant(s) rattaché(s) ou intervenant sans vœu déposé`,dataTable(['Enseignant','Dépt administratif','Statut'],silent.map(t=>[t.label,deptName(t.data.department),lab(t.data.status)])))+
 panel('Activités sans candidat',`${nocand.length} activité(s) des semestres ouverts aux vœux`,dataTable(['Niveau','Matière · activité','Volume'],nocand.map(a=>[lab(a.context.level),actLabel(a.id),fmt(a.data.hours)+' h'])))+
 panel('Activités avec plusieurs candidats',`${multi.length} activité(s) à arbitrer`,dataTable(['Matière · activité','Candidats'],multi.map(([a,n])=>[actLabel(a),n])))}
function chefDashboard(){let d=myDept(),acts=list('activity').filter(a=>a.context.department===d),reg=acts.filter(a=>a.data.category==='Réglementaire'),e=englishAgg(reg),rem=remainingRows(),open=rem.filter(r=>r.state!=='Affecté'),ws=deptWishes(),teachers=concernedTeachers(),answered=new Set(ws.map(w=>w.data.teacher)),camps=campaignsFor();
 let periods=new Set(camps.map(c=>c.data.period)),candidates=a=>ws.filter(w=>w.data.activity===a.id).length,wishable=acts.filter(a=>['Réglementaire','Formation complémentaire'].includes(a.data.category)&&periods.has(rec(a.context.semester)?.data.period));
 let loads=S.summary.loads.filter(l=>teachers.some(t=>t.id===l.teacher)),over=loads.filter(l=>l.status==='Dépassement'),valid=list('assignment').filter(a=>a.context.department===d&&a.data.state==='Validée');
 let alerts=[...over.map(l=>`${lab(l.teacher)} : dépassement de ${fmt(l.gap)} h Eq.C en période ${l.period} (total ENSF)`),...camps.filter(c=>c.data.status==='Ouverte').map(c=>`Campagne « ${c.data.name} » ouverte jusqu’au ${c.data.deadline}`),...(ws.filter(w=>w.data.state==='En attente').length?[`${ws.filter(w=>w.data.state==='En attente').length} vœu(x) en attente de décision`]:[]),...rem.filter(r=>r.state==='Dépassement').map(r=>`Dépassement de volume : ${actLabel(r.a.id)}`)];
 return head('Tableau de bord — Mon département',esc(deptName(d))+' · les enseignements de votre département et les enseignants ENSF qui y interviennent.',button('go-processing','Traiter les vœux →','primary'))+
 `<div class="cards">${metric('Enseignants intervenant',teachers.length,'Selon affectations, vœux et rattachement',3)}${metric('Fiches de vœux reçues',answered.size,`${ws.length} vœux · ${teachers.filter(t=>!answered.has(t.id)).length} sans réponse`,9)}${metric('Affectations validées',valid.length,`${open.length} activités restant à affecter`,4)}${metric('Anglais · département',fmt(e.rate)+' %',`${fmt(e.english)} h sur ${fmt(e.total)} h réglementaires`,6)}</div>`+
 `<div class="grid2">${panel('Charges des enseignants concernés','Charge globale ENSF, tous départements confondus',dataTable(['Enseignant','Période','Total ENSF (Eq.C)','Dont votre département','Cible','Situation'],loads.map(l=>[lab(l.teacher),'P'+l.period,fmt(l.assigned),fmt(l.depts[d]||0),fmt(l.target),l.status])))}${panel('Alertes','À traiter en priorité',`<div class="panelbody">${alerts.length?alerts.map(a=>`<div class="row"><span>${esc(a)}</span></div>`).join(''):'<p class="muted">Aucune alerte.</p>'}</div>`)}
 ${panel('Activités sans candidat',`${wishable.filter(a=>!candidates(a)).length} activité(s)`,`<div class="panelbody">${wishable.filter(a=>!candidates(a)).slice(0,8).map(a=>`<div class="row"><span>${esc(actLabel(a.id))}<small>${esc(lab(a.context.level))}</small></span>${button('assign-activity','Affecter','',`data-id="${a.id}"`)}</div>`).join('')||'<p class="muted">Aucune (ou aucune campagne ouverte).</p>'}${button('go-nowish','Voir tout →')}</div>`)}${panel('Activités avec plusieurs candidats',`${wishable.filter(a=>candidates(a)>1).length} activité(s)`,`<div class="panelbody">${wishable.filter(a=>candidates(a)>1).slice(0,8).map(a=>`<div class="row"><span>${esc(actLabel(a.id))}<small>${candidates(a)} candidats</small></span>${button('see-wishes','Arbitrer','',`data-id="${a.id}"`)}</div>`).join('')||'<p class="muted">Aucune.</p>'}</div>`)}</div>`+
 panel('Activités restant à affecter',`${open.length} activité(s)`,`<div class="panelbody">${button('go-remaining','Ouvrir l’écran « Activités restant à affecter » →','primary')}</div>`)}
/* ----- Espace enseignant ----- */
function myAssignments(){return list('assignment').filter(a=>a.data.teacher===S.me)}
function teacherPage(){if(!S.me)return head(page,'Espace enseignant')+`<div class="panel"><div class="empty"><h2>Aucune fiche enseignant pour l’année ${esc(currentYear().name)}</h2><p>Votre compte n’est lié à aucune fiche enseignant de cette année. Contactez l’administration.</p></div></div>`;
 return {'Accueil':teacherHome,'Mes vœux':myWishesView,'Mes affectations':myAssignmentsView,'Mon emploi du temps':myTimetableView,'Ma charge':myLoadView,'Mon profil':myProfileView}[page]()}
function teacherHome(){let t=rec(S.me),ws=list('wish').filter(w=>w.data.teacher===S.me),as=myAssignments(),valid=as.filter(a=>a.data.state==='Validée'),loads=S.summary.loads.filter(l=>l.teacher===S.me),ann=S.summary.annual.find(l=>l.teacher===S.me),en=valid.filter(a=>rec(a.data.language)?.data.code==='en');
 let open=list('campaign').filter(c=>c.data.status==='Ouverte'),alerts=[...open.map(c=>`Campagne de vœux « ${c.data.name} » ouverte jusqu’au ${c.data.deadline}${ws.some(w=>w.data.campaign===c.id)?'':' : vous n’avez pas encore déposé de vœu'}`),...loads.filter(l=>l.status!=='Charge atteinte'&&l.target!=null).map(l=>`Période ${l.period} : ${l.status.toLowerCase()} (${fmt(l.assigned)} h Eq.C / ${fmt(l.target)} h)`),...ws.filter(w=>w.data.state==='Refusée').map(w=>`Vœu refusé : ${actLabel(w.data.activity)}${w.data.decision_note?' — '+w.data.decision_note:''}`)];
 return head('Bonjour '+esc(t.data.first+' '+t.data.last),'Votre espace personnel ENSF : tous vos enseignements, tous départements confondus.',open.length?button('wish-new','+ Formuler des vœux','primary'):'')+
 `<div class="cards">${metric('Mes vœux',ws.filter(w=>w.data.state!=='Retirée').length,`${ws.filter(w=>w.data.state==='En attente').length} en attente · ${ws.filter(w=>w.data.state.startsWith('Acceptée')).length} acceptés`,9)}${metric('Mes affectations',valid.length,`${as.length-valid.length} en préparation · ${new Set(valid.map(a=>a.context.department)).size} département(s)`,4)}${metric('Ma charge ENSF',ann?fmt(ann.assigned)+' h':'—',ann?`Cible annuelle ${fmt(ann.target)} h Eq.C · ${ann.status}`:'',7)}${metric('En anglais',fmt(en.reduce((n,a)=>n+a.data.hours,0))+' h',`${new Set(en.map(a=>a.data.activity)).size} activité(s)`,6)}</div>`+
 panel('Alertes personnelles','',`<div class="panelbody">${alerts.length?alerts.map(a=>`<div class="row"><span>${esc(a)}</span></div>`).join(''):'<p class="muted">Aucune alerte.</p>'}</div>`)+
 panel('Mes enseignements en anglais','Affectations validées',dataTable(['Département','Niveau','Matière · activité','Public','Heures'],en.map(a=>[deptName(a.context.department),lab(a.context.level),actLabel(a.data.activity),rec(a.data.group)?.data.name,fmt(a.data.hours)])))}
function myWishesView(){let ws=list('wish').filter(w=>w.data.teacher===S.me).sort((a,b)=>(a.data.campaign+a.data.priority).localeCompare(b.data.campaign+b.data.priority)),open=list('campaign').filter(c=>c.data.status==='Ouverte');
 return head('Mes vœux','Exprimez vos souhaits pour des matières de n’importe quel département. Un vœu est une préférence, pas une affectation.',open.length&&!currentYear().closed?button('wish-new','+ Formuler des vœux','primary'):'')+
 `<div class="alert">${open.length?open.map(c=>`Campagne « ${esc(c.data.name)} » (semestre ${esc(c.data.period)}${c.data.department?', '+esc(deptName(c.data.department)):''}) : dépôt du ${esc(c.data.open)} au ${esc(c.data.deadline)}.`).join('<br>'):'Aucune campagne de vœux n’est ouverte actuellement.'} Chaque vœu est traité par le chef du département de la matière. Vous pouvez formuler plus de vœux que votre charge cible.</div>`+
 `<div class="panel"><div class="tablewrap"><table><thead><tr><th>Campagne</th><th>Département</th><th>Niveau</th><th>Matière · activité</th><th>Choix</th><th>Langue souhaitée</th><th>Observation</th><th>Décision</th><th class="noprint"></th></tr></thead><tbody>${ws.map(w=>{let c=rec(w.data.campaign),editable=w.data.state==='En attente'&&c?.data.status==='Ouverte'&&!currentYear().closed;return `<tr><td>${esc(c?.data.name)}</td><td>${esc(deptName(w.context.department))}</td><td>${esc(lab(w.context.level))}</td><td>${esc(actLabel(w.data.activity))}</td><td>${fmt(w.data.priority)}</td><td>${esc(lab(w.data.language))}</td><td>${esc(w.data.note||'')}</td><td>${wbadge(w.data.state)}${w.data.decision_note?`<small>${esc(w.data.decision_note)}</small>`:''}</td><td class="noprint"><div class="actions">${editable?button('wish-edit','Modifier','',`data-id="${w.id}"`)+button('wish-withdraw','Retirer','danger',`data-id="${w.id}"`):''}${button('history','Historique','',`data-id="${w.id}"`)}</div></td></tr>`}).join('')}</tbody></table></div>${ws.length?'':'<div class="empty"><h2>Aucun vœu</h2><p>Vos vœux apparaîtront ici.</p></div>'}<div class="tablefoot">${ws.length} vœu(x)</div></div>`}
function myAssignmentsView(){let as=myAssignments();return head('Mes affectations','Toutes vos affectations ENSF, quel que soit le département.',button('print','PDF / Imprimer'))+dataTable(['Département','Niveau','Semestre','Matière · activité','Public','Heures','Eq. cours','Langue','Origine','État'],as.map(a=>[deptName(a.context.department),lab(a.context.level),rec(a.context.semester)?.data.name,actLabel(a.data.activity),rec(a.data.group)?.data.name,fmt(a.data.hours),fmt(a.data.hours*factorOf(a.data.activity)),lab(a.data.language),a.data.wish?'Vœu':'Manuelle',a.data.state]))}
let myPeriod='1';
function pauseRow(i,n){return i&&S.timeslots[i-1][1]!==S.timeslots[i][0]?`<div class="hour pause">${S.timeslots[i-1][1]}<br>Pause</div>`+'<div class="pause"></div>'.repeat(n):''}
function weekGrid(slots){let days=S.days,times=S.timeslots.map(t=>t[0]);
 return `<div class="panel"><div class="tablewrap"><div class="weekgrid"><div class="day">Horaire</div>${days.map(d=>`<div class="day">${d}</div>`).join('')}${times.map((time,i)=>pauseRow(i,days.length)+`<div class="hour"><b>${time}</b><br>${S.timeslots[i][1]}</div>`+days.map(day=>`<div>${slots.filter(r=>r.data.day===day&&r.data.start>=time&&r.data.start<S.timeslots[i][1]).map(r=>{let a=rec(r.data.assignment);return `<div class="lesson"><b>${esc(r.data.start)} · ${esc(deptName(r.context.department))}</b><br>${esc(actLabel(a.data.activity))}<small>${esc(lab(a.context.level))}</small><small>${esc(rec(a.data.group)?.data.name)} · ${esc(lab(r.data.room))} · ${esc(lab(a.data.language))}</small><small>Sem. ${esc(r.data.weeks)}</small></div>`}).join('')}</div>`).join('')).join('')}</div></div></div>`}
function myTimetableView(){let slots=list('slot').filter(s=>rec(s.data.assignment)?.data.teacher===S.me&&rec(s.context.semester)?.data.period===myPeriod),today=S.today,next=list('session').filter(s=>rec(s.data.assignment)?.data.teacher===S.me&&s.data.date>=today).sort((a,b)=>(a.data.date+a.data.start).localeCompare(b.data.date+b.data.start)).slice(0,30);
 return head('Mon emploi du temps','Un seul emploi du temps regroupant vos séances dans tous les départements.',button('print','PDF / Imprimer'))+`<div class="toolbar"><select id="myPeriod"><option value="1" ${myPeriod==='1'?'selected':''}>Semestres impairs (période 1)</option><option value="2" ${myPeriod==='2'?'selected':''}>Semestres pairs (période 2)</option></select></div>`+weekGrid(slots)+panel('Prochaines séances datées','',dataTable(['Date','Début','Durée','Département','Matière · activité','Public','Salle','Statut'],next.map(s=>{let a=rec(s.data.assignment);return [s.data.date,s.data.start,fmt(s.data.duration)+' h',deptName(s.context.department),actLabel(a.data.activity),rec(a.data.group)?.data.name,lab(s.data.room),sessionState(s)]})))}
function myLoadView(){let loads=S.summary.loads.filter(l=>l.teacher===S.me),ann=S.summary.annual.find(l=>l.teacher===S.me);
 return head('Ma charge','Charge globale ENSF, tous départements confondus (équivalent cours).',button('print','PDF / Imprimer'))+dataTable(['Période','Cours (h)','TD (h)','TP (h)','Affectée Eq.C','Par département','Planifiée','Réalisée','Missions','Cible','Écart','Situation'],loads.map(l=>['P'+l.period,fmt(l.types.Cours),fmt(l.types.TD),fmt(l.types.TP),fmt(l.assigned),deptSplit(l.depts),fmt(l.planned),fmt(l.actual),fmt(l.extra),fmt(l.target),fmt(l.gap),l.status]))+
 (ann?panel('Charge annuelle','',`<div class="panelbody"><div class="row"><span>Total affecté (Eq.C)</span><b>${fmt(ann.assigned)} h</b></div><div class="row"><span>Missions reconnues</span><b>${fmt(ann.extra)} h</b></div><div class="row"><span>Cible annuelle</span><b>${fmt(ann.target)} h</b></div><div class="row"><span>Situation</span><b>${esc(ann.status)} (${fmt(ann.gap)} h)</b></div><div class="row"><span>Répartition</span><b>${esc(deptSplit(ann.depts))}</b></div><div class="row"><span>Heures enseignées en anglais</span><b>${fmt(ann.english)} h</b></div></div>`):'')}
function myProfileView(){let t=rec(S.me),d=t.data;return head('Mon profil','Vos informations ENSF. Seuls les champs ci-dessous sont modifiables par vous.')+
 `<div class="grid2">${panel('Fiche enseignant','',`<div class="panelbody"><div class="row"><span>Nom</span><b>${esc(d.last+' '+d.first)}</b></div><div class="row"><span>Grade</span><b>${esc(lab(d.grade))}</b></div><div class="row"><span>Statut</span><b>${esc(lab(d.status))}</b></div><div class="row"><span>Département administratif</span><b>${esc(deptName(d.department))}</b></div><div class="row"><span>Type de charge</span><b>${esc(d.load)}</b></div><form id="profile-form"><div class="formgrid" style="margin-top:15px"><label class="field">Niveau d’anglais<select name="english_level">${S.schema.teacher.fields.find(f=>f.key==='english_level').options.map(o=>`<option ${o===(d.english_level||'Non renseigné')?'selected':''}>${o}</option>`).join('')}</select></label><label class="field">Je peux enseigner en anglais<select name="english_ok">${['Non déclaré','Oui','Non'].map(o=>`<option ${o===(d.english_ok||'Non déclaré')?'selected':''}>${o}</option>`).join('')}</select></label><label class="field">Courriel<input name="email" value="${esc(d.email||'')}"></label><label class="field wide">Observation<textarea name="english_note">${esc(d.english_note||'')}</textarea></label></div></form><p class="muted small">Le niveau d’anglais est informatif : la décision d’affectation appartient au chef de département.</p>${currentYear().closed?'':button('profile-save','Enregistrer','primary')}</div>`)}${panel('Mot de passe','10 caractères minimum',`<div class="panelbody"><form id="password-form"><label class="field">Mot de passe actuel<input type="password" name="old" autocomplete="current-password" required></label><label class="field">Nouveau mot de passe<input type="password" name="new" minlength="10" autocomplete="new-password" required></label></form>${button('password-save','Changer le mot de passe')}</div>`)}</div>`}
function wishDialog(w=null){let open=list('campaign').filter(c=>c.data.status==='Ouverte'&&c.data.open<=S.today&&c.data.deadline>=S.today);if(!open.length)throw Error('Aucune campagne ouverte au dépôt aujourd’hui.');
 let langs=list('language').filter(l=>['fr','en'].includes(l.data.code));
 if(w){openDialog('Modifier mon vœu',`<p><b>${esc(actLabel(w.data.activity))}</b> · ${esc(lab(w.context.level))} · ${esc(deptName(w.context.department))}</p><form id="editor"><div class="formgrid"><label class="field">Priorité<select name="priority">${[...Array(10)].map((_,i)=>`<option value="${i+1}" ${w.data.priority===i+1?'selected':''}>Choix ${i+1}</option>`).join('')}</select></label><label class="field">Langue souhaitée<select name="language">${langs.map(l=>`<option value="${l.id}" ${l.id===w.data.language?'selected':''}>${esc(l.data.name)}</option>`).join('')}</select></label><label class="field wide">Observation<textarea name="note">${esc(w.data.note||'')}</textarea></label></div></form>`,button('close','Annuler')+button('wish-update','Enregistrer','primary',`data-id="${w.id}"`));return}
 openDialog('Formuler des vœux',`<form id="wish-form"><div class="formgrid"><label class="field">Campagne<select name="campaign" id="wish-campaign">${open.map(c=>`<option value="${c.id}">${esc(c.data.name)} · semestre ${esc(c.data.period)}${c.data.department?' · '+esc(deptName(c.data.department)):''}</option>`).join('')}</select></label><label class="field">Matière (tous départements)<input class="refsearch" id="wish-search" placeholder="Rechercher…"><select name="subject" id="wish-subject"></select></label></div><div id="wish-activities" style="margin-top:15px"></div></form><p class="muted small">Cochez les activités souhaitées (Cours, TD, TP), puis indiquez pour chacune votre priorité et la langue souhaitée. Vos vœux ne sont pas limités par votre charge.</p>`,button('close','Annuler')+button('wish-submit','Déposer mes vœux','primary'));wishSubjects()}
function wishSubjects(){let c=rec($('#wish-campaign').value),q=($('#wish-search').value||'').toLowerCase(),mine=new Set(list('wish').filter(w=>w.data.teacher===S.me&&w.data.campaign===c.id&&w.data.state!=='Retirée').map(w=>w.data.activity));
 let acts=list('activity').filter(a=>['Réglementaire','Formation complémentaire'].includes(a.data.category)&&rec(a.context.semester)?.data.period===c.data.period&&(!c.data.department||a.context.department===c.data.department)&&!mine.has(a.id));
 let subs=[...new Set(acts.map(a=>a.data.subject))].map(rec).filter(s=>!q||(s.label+' '+lab(s.context.level)+' '+deptName(s.context.department)).toLowerCase().includes(q)).sort((a,b)=>a.label.localeCompare(b.label,'fr'));
 $('#wish-subject').innerHTML=`<option value="">Choisir… (${subs.length})</option>`+subs.map(s=>`<option value="${s.id}">${esc(s.data.name)} · ${esc(lab(s.context.level))} · ${esc(deptName(s.context.department))}</option>`).join('');$('#wish-activities').innerHTML=''}
function wishActivities(){let c=rec($('#wish-campaign').value),sid=$('#wish-subject').value,langs=list('language').filter(l=>['fr','en'].includes(l.data.code)),mine=new Set(list('wish').filter(w=>w.data.teacher===S.me&&w.data.campaign===c.id&&w.data.state!=='Retirée').map(w=>w.data.activity)),n=list('wish').filter(w=>w.data.teacher===S.me&&w.data.campaign===c.id&&w.data.state!=='Retirée').length;
 let acts=list('activity').filter(a=>a.data.subject===sid&&['Réglementaire','Formation complémentaire'].includes(a.data.category)&&!mine.has(a.id));
 $('#wish-activities').innerHTML=acts.map((a,i)=>`<div class="row" data-wish-activity="${a.id}"><label style="display:flex;gap:10px;align-items:center;min-width:160px"><input type="checkbox" name="pick" value="${a.id}"> <b>${esc(lab(a.data.type))}</b> · ${fmt(a.data.hours)} h</label><select name="priority-${a.id}" aria-label="Priorité">${[...Array(10)].map((_,k)=>`<option value="${k+1}" ${k===Math.min(9,n+i)?'selected':''}>Choix ${k+1}</option>`).join('')}</select><select name="language-${a.id}" aria-label="Langue souhaitée">${langs.map(l=>`<option value="${l.id}">${esc(l.data.name)}</option>`).join('')}</select><input name="note-${a.id}" placeholder="Observation (facultatif)"></div>`).join('')||'<p class="muted">Aucune activité disponible pour cette matière.</p>'}
async function historyDialog(id){let rr=await api('history?id='+encodeURIComponent(id));openDialog('Historique · '+lab(id),rr.map(h=>{let b=JSON.parse(h.before_data||'null'),a=JSON.parse(h.after_data||'null'),bd=b?.data||{},ad=a?.data||{},keys=[...new Set([...Object.keys(bd),...Object.keys(ad)])].filter(k=>JSON.stringify(bd[k])!==JSON.stringify(ad[k])&&!['updated','decision_date','decided_by','submitted'].includes(k));return `<div class="row"><div><strong>${esc(h.at.replace('T',' ').slice(0,16))} · ${esc(h.user)} · ${esc(h.action)}</strong>${keys.map(k=>`<small>${esc(S.schema[a?.kind||b?.kind]?.fields.find(f=>f.key===k)?.label||k)} : ${esc(rec(bd[k])?.label??bd[k]??'—')} → ${esc(rec(ad[k])?.label??ad[k]??'—')}</small>`).join('')}</div></div>`}).join('')||'<p class="muted">Aucun historique.</p>',button('close','Fermer'))}
function decideDialog(w,state){openDialog('Décision · '+state,`<p><b>${esc(actLabel(w.data.activity))}</b> · ${esc(lab(w.data.teacher))} · choix ${fmt(w.data.priority)} · ${esc(lab(w.data.language))}</p><form id="decide-form"><label class="field wide">Commentaire${state==='Acceptée'?' (facultatif)':''}<textarea name="decision_note">${esc(w.data.decision_note||'')}</textarea></label></form>`,button('close','Annuler')+button('decide-confirm','Confirmer : '+state,state==='Refusée'?'danger':'primary',`data-id="${w.id}" data-state="${state}"`))}
async function saveRecord(r,changes){let v=await api('save',{year:S.year,kind:r.kind,id:r.id,revision:r.revision,active:r.active,data:{...r.data,...changes}});return v}
/* ----- Comptes ges-ped ----- */
let USERS=[];
const ROLE_HELP={'Administrateur':'Administration et direction : accès global, gestion des comptes.','Direction / DAP':'Direction pédagogique : accès global, sans gestion des comptes.','Chef de département':'Gère les enseignements de son département. Associez sa fiche enseignant s’il enseigne aussi.','Enseignant':'Espace personnel : vœux, affectations, emploi du temps, charge.','Consultation':'Lecture seule.'};
function teacherByPerson(p){return list('teacher',false).find(t=>t.data.person===p)}
function publicUrl(){return S.public_url||location.origin}
async function usersPage(){USERS=await api('users');let el=$('#users-page');if(!el)return;let linked=new Set(USERS.map(u=>u.teacher).filter(Boolean)),free=list('teacher').filter(t=>!linked.has(t.data.person));
 el.innerHTML=`<div class="alert">Chaque compte reçoit un identifiant (ex. <b>n.laouar</b>) et un mot de passe temporaire unique, affiché une seule fois. L’utilisateur le change obligatoirement à sa première connexion. Lien à transmettre : <b>${esc(publicUrl())}</b></div><div class="toolbar">${button('account-new','+ Compte chef de département','primary','data-role="Chef de département"')}${button('account-new','+ Compte enseignant','','data-role="Enseignant"')}${button('account-new','+ Compte administration / direction','','data-role="Direction / DAP"')}</div>`+
 `<div class="panel"><div class="tablewrap"><table><thead><tr><th>Identifiant</th><th>Nom</th><th>Rôle</th><th>Périmètre</th><th>État</th><th>Dernière connexion</th><th class="noprint">Actions</th></tr></thead><tbody>${USERS.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.full_name||'—')}</td><td>${esc(u.role)}</td><td>${esc(u.role==='Chef de département'?deptName(u.department):u.teacher?(teacherByPerson(u.teacher)?.label||'Fiche enseignant'):'ENSF')}</td><td>${u.active?(u.must_change?badge('1re connexion à faire'):badge('Actif')):badge('Archivé')}</td><td>${esc((u.last_login||'—').replace('T',' ').slice(0,16))}</td><td class="noprint"><div class="actions">${button('account-edit','Modifier','',`data-id="${u.id}"`)}${button('account-reset','Nouveau mot de passe','',`data-id="${u.id}"`)}${u.id!==S.user.id?button('account-toggle',u.active?'Désactiver':'Réactiver',u.active?'danger':'',`data-id="${u.id}"`):''}</div></td></tr>`).join('')}</tbody></table></div><div class="tablefoot">${USERS.length} compte(s)</div></div>`+
 panel('Enseignants sans compte',`${free.length} fiche(s) · un enseignant = un seul compte ENSF`,free.length?`<div class="tablewrap"><table><tbody>${free.map(t=>`<tr><td>${esc(t.label)}</td><td>${esc(deptName(t.data.department))}</td><td class="noprint">${button('account-new','Créer le compte','',`data-role="Enseignant" data-person="${esc(t.data.person)}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="panelbody"><p class="muted">Tous les enseignants actifs ont un compte.</p></div>')}
function accountForm(u={}){let edit=!!u.id,teachers=list('teacher',false);
 openDialog(edit?'Modifier le compte':'Nouveau compte',`<form id="account-form"><input type="hidden" name="id" value="${esc(u.id||'')}"><div class="formgrid"><label class="field">Type de compte<select name="role" id="account-role">${S.roles.map(r=>`<option ${r===u.role?'selected':''}>${r}</option>`).join('')}</select></label><label class="field" id="account-dept">Département dirigé<select name="department">${opts(list('department'),u.department,'Choisir…')}</select></label><label class="field" id="account-teacher">Fiche enseignant<select name="teacher" id="account-person"><option value="">Choisir… (facultatif pour un chef)</option>${teachers.map(t=>`<option value="${esc(t.data.person)}" ${t.data.person===u.teacher?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><label class="field" id="account-fullname">Nom complet (Prénom Nom)<input name="full_name" id="account-full" value="${esc(u.full_name||'')}"></label><label class="field">Identifiant de connexion<input name="name" id="account-name" required pattern="[a-z0-9][a-z0-9._\-]{1,39}" value="${esc(u.name||'')}" autocapitalize="none" spellcheck="false"></label>${edit?`<label class="field">État<select name="active"><option value="1">Actif</option><option value="0" ${u.active?'':'selected'}>Désactivé</option></select></label>`:''}</div><p class="muted small" id="account-help"></p></form>${edit?'':'<p class="small muted">Un mot de passe temporaire unique sera généré et affiché une seule fois.</p>'}`,button('close','Annuler')+(edit?'':button('account-suggest','Proposer l’identifiant'))+button('account-save',edit?'Enregistrer':'Créer le compte','primary'));
 accountFields();if(!edit)suggestName()}
function accountFields(){let r=$('#account-role')?.value;if(!r)return;$('#account-dept').hidden=r!=='Chef de département';$('#account-teacher').hidden=!['Enseignant','Chef de département'].includes(r);$('#account-fullname').hidden=r==='Enseignant';$('#account-help').textContent=ROLE_HELP[r]||''}
async function suggestName(force){let p=$('#account-person')?.value,first='',last='';let t=p&&teacherByPerson(p);if(t){first=t.data.first;last=t.data.last;if(!$('#account-full').value)$('#account-full').value=first+' '+last}else{let parts=($('#account-full')?.value||'').trim().split(/\s+/);first=parts.shift()||'';last=parts.join(' ')}if(!first&&!last)return;if(!force&&$('#account-name').dataset.touched)return;let r=await api(`username-suggest?first=${encodeURIComponent(first)}&last=${encodeURIComponent(last)}&id=${encodeURIComponent($('#account-form [name=id]').value)}`);$('#account-name').value=r.name}
async function saveAccount(){let f=$('#account-form');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));d.name=d.name.trim().toLowerCase();if(d.active!==undefined)d.active=Number(d.active);d.action=d.id?'update':'create';if(!d.id)delete d.id;let r=await api('users',d);$('#dialog').close();if(r.temporary)credentials(r.user,r.temporary,'Compte créé');else toast('Compte enregistré.');usersPage()}
function credentials(u,temp,title){openDialog(title+' · informations à transmettre',`<div class="credentials" id="credentials-text">Lien : ${esc(publicUrl())}\nIdentifiant : ${esc(u.name)}\nMot de passe temporaire : ${esc(temp)}</div><p class="small muted">${esc(u.full_name||'')} · ${esc(u.role)}. Ce mot de passe ne sera plus jamais affiché. À sa première connexion, l’utilisateur devra choisir son propre mot de passe.</p>`,button('copy-credentials','Copier le texte','primary')+button('close','Fermer'))}
function feedbackDialog(){openDialog('Signaler un problème / faire une remarque',`<form id="feedback-form"><div class="formgrid"><label class="field">Type<select name="type"><option>À corriger</option><option>Bloquant</option><option>Amélioration</option></select></label><label class="field">Page concernée<input value="${esc(page)}" disabled></label><label class="field wide">Votre remarque<textarea name="comment" required minlength="3" placeholder="Ce que vous faisiez, ce qui s’est passé, ce que vous attendiez…"></textarea></label></div></form>`,button('close','Annuler')+button('feedback-send','Envoyer','primary'))}
async function feedbackPage(){let items=await api('feedback'),el=$('#feedback-page');if(!el)return;
 el.innerHTML=`<p class="muted">Remarques transmises par les utilisateurs pilotes avec le bouton « Signaler un problème ».</p><div class="panel"><div class="tablewrap"><table><thead><tr><th>Date</th><th>Utilisateur</th><th>Page</th><th>Type</th><th>Remarque</th><th>Suivi</th></tr></thead><tbody>${items.map(f=>`<tr><td>${esc(f.at.replace('T',' ').slice(0,16))}</td><td>${esc(f.user_name)}<small>${esc(f.role||'')}</small></td><td>${esc(f.page||'')}</td><td><span class="badge ${f.type==='Bloquant'?'red':f.type==='À corriger'?'amber':''}">${esc(f.type)}</span></td><td style="white-space:pre-wrap">${esc(f.comment)}</td><td><select data-feedback="${f.id}">${['Nouveau','En cours','Traité','Sans suite'].map(x=>`<option ${x===f.status?'selected':''}>${x}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>${items.length?'':'<div class="empty"><h2>Aucune remarque pour le moment</h2></div>'}<div class="tablefoot">${items.length} remarque(s)</div></div>`}
async function action(a,el){
 if(['print','report-xlsx'].includes(a)&&page==='Rapports'&&report==='Fiche individuelle'&&(!reportTeacher||!reportPeriod))throw Error('Choisissez un enseignant et une période pour éditer sa fiche individuelle.');
 if(['print','report-xlsx'].includes(a)&&page==='Rapports'&&report==='Fiche de vœux individuelle'&&!reportTeacher)throw Error('Choisissez un enseignant pour éditer sa fiche de vœux.');
 if(a==='logout'){await api('logout',{});S=null;await start();return}
 if(a==='close'){$('#dialog').close();return}
 if(a==='go-processing')return navigate('Vœux','processing');if(a==='go-nowish')return navigate('Vœux','nowish');if(a==='go-remaining')return navigate('Affectations','remaining');
 if(a==='see-wishes'){wActivity=el.dataset.id;return navigate('Vœux','processing')}if(a==='clear-wactivity'){wActivity='';render();return}
 if(a==='assign-activity')return editForm('assignment',null,{activity:el.dataset.id});
 if(a==='decide')return decideDialog(rec(el.dataset.id),el.dataset.state);
 if(a==='decide-confirm'){let w=rec(el.dataset.id);await saveRecord(w,{state:el.dataset.state,decision_note:new FormData($('#decide-form')).get('decision_note')});$('#dialog').close();await load(S.year);toast('Décision enregistrée.');return}
 if(a==='wish-assign'){let w=rec(el.dataset.id),act=rec(w.data.activity);return editForm('assignment',null,{activity:w.data.activity,teacher:w.data.teacher,language:w.data.language,hours:act.data.hours,wish:w.id,state:'Brouillon'})}
 if(a==='history')return historyDialog(el.dataset.id);
 if(a==='wish-new')return wishDialog();if(a==='wish-edit')return wishDialog(rec(el.dataset.id));
 if(a==='wish-update'){let f=Object.fromEntries(new FormData($('#editor')).entries());await saveRecord(rec(el.dataset.id),{priority:Number(f.priority),language:f.language,note:f.note});$('#dialog').close();await load(S.year);toast('Vœu modifié.');return}
 if(a==='wish-withdraw'&&await ask('Retirer ce vœu ? Il restera visible dans votre historique.')){await saveRecord(rec(el.dataset.id),{state:'Retirée'});await load(S.year);toast('Vœu retiré.');return}
 if(a==='wish-submit'){let f=new FormData($('#wish-form')),picks=f.getAll('pick');if(!picks.length)throw Error('Cochez au moins une activité.');let r=await api('wish-batch',{year:S.year,campaign:f.get('campaign'),teacher:S.me,items:picks.map(id=>({activity:id,priority:Number(f.get('priority-'+id)),language:f.get('language-'+id),note:f.get('note-'+id)}))});$('#dialog').close();await load(S.year);toast(r.count+' vœu(x) déposé(s).');return}
 if(a==='profile-save'){let f=Object.fromEntries(new FormData($('#profile-form')).entries());await saveRecord(rec(S.me),f);await load(S.year);toast('Profil enregistré.');return}
 if(a==='password-save'){let f=$('#password-form');if(!f.reportValidity())return;await api('password',Object.fromEntries(new FormData(f).entries()));f.reset();toast('Mot de passe modifié.');return}
 if(a==='go-programs')return navigate('Programmes');if(a==='go-assignments')return navigate('Affectations');if(a==='go-english'){report='Taux d’anglais';return navigate('Rapports')}
 if(a==='add')return editForm(tab);if(a==='edit'){let r=rec(el.dataset.id);return editForm(r.kind,r.id)}
 if(a==='duplicate'){let r=rec(el.dataset.id);return editForm(r.kind,null,{...r.data,state:'Brouillon'})}
 if(a==='save')return saveEditor();if(a==='archive'){if(await ask('Confirmer le changement d’état de cette fiche ?'))return saveEditor(edit.active?0:1)}
 if(a==='delete'&&await ask('Supprimer cette fiche jamais utilisée ?')){await api('delete',{id:edit.id});$('#dialog').close();await load(S.year);toast('Fiche supprimée.');return}
 if(a==='print'){window.print();return}if(a==='sort'){sortAsc=!sortAsc;render();return}
 if(a==='export'){window.location.href='/api/export?year='+encodeURIComponent(S.year)+'&kind='+tab;return}
 if(a==='report-xlsx')return downloadReport();if(a==='program-report'){report='Programme';reportSemester=filter;return navigate('Rapports')}
 if(a==='load-report'){report='Charges enseignants';reportTeacher=filter;return navigate('Rapports')}
 if(a==='clear-report'){reportTeacher=reportSemester=reportPeriod=reportRoom=reportLevel=reportDepartment=reportTrack=reportSpecialty='';render();return}
 if(a==='add-slot')return editForm('slot');if(a==='place')return editForm('slot',null,{day:el.dataset.day,start:el.dataset.time});
 if(a==='generate'&&await ask('Valider les séries de l’année et générer leurs séances datées ? Les séries générées seront verrouillées.')){let v=await api('generate',{year:S.year});await load(S.year);toast(v.count+' séances générées.');return}
 if(a==='makeup'){let r=rec(edit.id);$('#dialog').close();return editForm('session',null,{assignment:r.data.assignment,room:r.data.room,duration:r.data.duration-r.data.actual,replaces:r.id})}
 if(a==='switch-year'){await load(el.dataset.id);return}
 if(a==='duplicate-year'){openDialog('Créer une nouvelle année',`<form id="year-form"><label class="field">Libellé de la nouvelle année<input name="name" required placeholder="2027 / 2028"></label></form><p class="muted small" style="margin-top:15px">Copie des référentiels et de l’annuaire, sans affectations, emplois du temps ni séances. Les dates des semestres seront à renseigner.</p>`,button('close','Annuler')+button('year-create','Créer','primary',`data-id="${el.dataset.id}"`));return}
 if(a==='year-create'){let f=$('#year-form');if(!f.reportValidity())return;let v=await api('year',{action:'duplicate',source:el.dataset.id,name:new FormData(f).get('name')});$('#dialog').close();filter='';await load(v.year);toast('Nouvelle année créée.');return}
 if(a==='close-year'&&await ask('Clôturer définitivement cette année ? Elle deviendra consultable uniquement. Effectuez une sauvegarde avant la clôture.')){await api('year',{action:'close',year:el.dataset.id});await load(S.year);toast('Année clôturée.');return}
 if(a==='backup'){window.location.href='/api/backup';return}
 if(a==='restore'){chooseFile('.json',async f=>{let p=await api('restore-preview',{backup:JSON.parse(await f.text())});openDialog('Confirmer la restauration',`<div class="alert">La restauration remplacera les données pédagogiques actuelles. Une copie de sécurité sera conservée automatiquement.</div><p>Sauvegarde du ${esc(p.created)}<br>${p.years} années · ${p.records} fiches</p><label class="field">Votre mot de passe administrateur<input type="password" id="restore-password" autocomplete="current-password"></label>`,button('close','Annuler')+button('restore-confirm','Restaurer','primary',`data-token="${p.token}"`))});return}
 if(a==='restore-confirm'){await api('restore',{token:el.dataset.token,password:$('#restore-password').value});$('#dialog').close();await load();toast('Sauvegarde restaurée.');return}
 if(a==='import')return importFile();if(a==='confirm-import'){let r=await api('import',{token:el.dataset.token});$('#dialog').close();await load(S.year);toast(r.count+' fiches importées.');return}
 if(a==='logout-simple'){await api('logout',{});S=null;CSRF='';return start()}
 if(a==='account-new')return accountForm({role:el.dataset.role||'Enseignant',teacher:el.dataset.person||''});
 if(a==='account-edit')return accountForm(USERS.find(u=>u.id===el.dataset.id));
 if(a==='account-save')return saveAccount();
 if(a==='account-suggest')return suggestName(true);
 if(a==='account-reset'){let u=USERS.find(x=>x.id===el.dataset.id);if(!await ask(`Générer un nouveau mot de passe temporaire pour « ${u.name} » ? L’ancien ne fonctionnera plus et ses sessions seront fermées.`))return;let r=await api('users',{action:'reset',id:u.id});credentials(r.user,r.temporary,'Mot de passe réinitialisé');return usersPage()}
 if(a==='account-toggle'){let u=USERS.find(x=>x.id===el.dataset.id);if(!await ask(`${u.active?'Désactiver':'Réactiver'} le compte « ${u.name} » ?`))return;await api('users',{...u,action:'update',active:u.active?0:1});toast('Compte mis à jour.');return usersPage()}
 if(a==='copy-credentials'){let t=$('#credentials-text').innerText;try{await navigator.clipboard.writeText(t);toast('Informations copiées. Collez-les dans votre message.')}catch{let r=document.createRange();r.selectNodeContents($('#credentials-text'));getSelection().removeAllRanges();getSelection().addRange(r);toast('Texte sélectionné : copiez-le avec Ctrl+C.')}return}
 if(a==='feedback')return feedbackDialog();
 if(a==='feedback-send'){let f=$('#feedback-form');if(!f.reportValidity())return;let d=Object.fromEntries(new FormData(f));await api('feedback',{...d,page:page+(tab?' · '+tab:'')});$('#dialog').close();toast('Merci ! Votre remarque a été transmise à l’administrateur.');return}
 if(a==='audit'){let rr=await api('audit?year='+S.year);$('#audit-content').innerHTML=rr.map(r=>`<details style="margin:15px 0"><summary>${esc(r.at)} · ${esc(r.user)} · ${esc(r.action)} · ${esc(S.schema[r.kind]?.title||r.kind)}</summary><pre class="source">Avant : ${esc(r.before_data)}\nAprès : ${esc(r.after_data)}</pre></details>`).join('');return}
}
document.addEventListener('click',async e=>{let el=e.target.closest('[data-action],[data-nav],[data-tab]');if(!el)return;try{if(el.dataset.nav)return navigate(el.dataset.nav,el.dataset.tab);if(el.dataset.tab){tab=el.dataset.tab;filter='';search='';return render()}if(el.dataset.action){el.disabled=true;await action(el.dataset.action,el)}}catch(err){if($('#dialog').open&&$('#form-error'))$('#form-error').textContent=err.message;else toast(err.message)}finally{el.disabled=false}});
document.addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;search=e.target.value;$('#page').innerHTML=modulePage();let f=$('#search');f.focus();f.setSelectionRange(pos,pos)}if(e.target.id==='wish-search'){wishSubjects();return}if(e.target.id==='account-name'){e.target.dataset.touched='1';return}if(e.target.id==='account-full'){suggestName();return}if(e.target.dataset.searchRef){let name=e.target.dataset.searchRef,q=e.target.value.toLowerCase();$$(`#editor select[name="${name}"] option`).forEach(o=>o.hidden=!!o.value&&!o.textContent.toLowerCase().includes(q))}});
document.addEventListener('change',async e=>{try{let id=e.target.id;if(id==='year'){filter='';await load(e.target.value);return}if(id==='filter'){filter=e.target.value;render();return}
 let fl={remState:v=>remState=v,remLevel:v=>remLevel=v,wCampaign:v=>wCampaign=v,wState:v=>wState=v,wTeacher:v=>wTeacher=v,wType:v=>wType=v,wLevel:v=>wLevel=v,myPeriod:v=>myPeriod=v};if(fl[id]){fl[id](e.target.value);render();return}
 if(id==='wish-campaign'){wishSubjects();return}
 if(id==='account-role'){accountFields();return}if(id==='account-person'){suggestName(true);return}if(e.target.dataset.feedback){await api('feedback-status',{id:e.target.dataset.feedback,status:e.target.value});toast('Suivi enregistré.');return}if(id==='wish-subject'){wishActivities();return}if(id==='status'){status=e.target.value;render();return}if(id==='report'){report=e.target.value;reportTeacher=reportSemester=reportPeriod=reportRoom=reportLevel=reportDepartment=reportTrack=reportSpecialty='';render();return}if(id.startsWith('report')){let v=e.target.value;switch(id){case'reportTeacher':reportTeacher=v;break;case'reportSemester':reportSemester=v;break;case'reportPeriod':reportPeriod=v;break;case'reportRoom':reportRoom=v;break;case'reportLevel':reportLevel=v;break;case'reportDepartment':reportDepartment=v;break;case'reportTrack':reportTrack=v;break;case'reportSpecialty':reportSpecialty=v;break}render();return}if(e.target.closest('#editor')&&edit.kind==='assignment'){let d=formData();if(e.target.name==='activity'){for(let key of ['group']){let sel=$(`#editor select[name="${key}"]`),rr=candidates('assignment',key,d,edit.id);sel.innerHTML=opts(rr,'','Choisir…')}$('#editor input[name="hours"]').value=rec(d.activity)?.data.hours||''}assignmentHint()}}catch(err){toast(err.message)}});
function brand(){return `<div class="brand"><div class="mark">${LEAF}</div><div><strong>ges-ped</strong><small>GESTION PÉDAGOGIQUE ENSF</small></div></div>`}
const LEAF='<svg viewBox="0 0 24 24" width="26" height="26" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 22V11 M12 11c-4 0-7-3-7-8 5 0 7 3 7 8z M12 14c3 0 6-2 6-6-4 0-6 2-6 6z"/></svg>';
function loginShell(inner){return `<div class="login"><div class="login-aside">${brand()}<div><div class="eyebrow" style="color:#b9d1a0">École Nationale Supérieure des Forêts · Khenchela</div><h1>ges-ped</h1><p>Gestion pédagogique ENSF : vœux, affectations, charges et emplois du temps, dans un espace commun.</p></div><small style="color:#a6c1af">Version ${esc(STATUS.edition)} ${esc(STATUS.version)}</small></div><div class="login-main">${inner}</div></div>`}
async function start(message=''){try{STATUS=await api('status')}catch{}document.title=STATUS.title||'ges-ped — Gestion pédagogique ENSF';
 if(!STATUS.setup){try{await load();return}catch(e){if(e.status===403)return forcedChange()}}
 $('#app').innerHTML=loginShell(`<form id="login-form"><div class="eyebrow">${STATUS.setup?'PREMIÈRE INSTALLATION':'CONNEXION'}</div><h1>ges-ped</h1><p class="muted">${STATUS.setup?'Créez le premier compte administrateur.':'Connectez-vous avec l’identifiant qui vous a été transmis.'}</p><div class="form-error" id="login-error" role="alert">${esc(message&&!message.startsWith('Session')?'':message)}</div><label class="field">Identifiant<input name="name" required autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="ex. n.laouar" autofocus></label><label class="field">Mot de passe<input type="password" name="password" required ${STATUS.setup?'minlength="10"':''} autocomplete="${STATUS.setup?'new-password':'current-password'}"></label><button class="primary" type="submit">${STATUS.setup?'Créer le compte':'Se connecter'}</button></form>`);
 $('#login-form').addEventListener('submit',async e=>{e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;try{let d=Object.fromEntries(new FormData(e.target));d.name=d.name.trim().toLowerCase();let r=await api(STATUS.setup?'setup':'login',d);if(r.must_change)return forcedChange(d.password);await load()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}})
}
async function forcedChange(temp=''){let me=await api('me');CSRF=me.csrf;
 $('#app').innerHTML=loginShell(`<form id="change-form"><div class="eyebrow">PREMIÈRE CONNEXION</div><h1>Nouveau mot de passe</h1><p class="muted">Bonjour ${esc(me.user.full_name||me.user.name)}. Vous devez modifier votre mot de passe avant de continuer.</p><div class="form-error" id="login-error" role="alert"></div><label class="field">Mot de passe temporaire<input type="password" name="old" required autocomplete="current-password" value="${esc(temp)}"></label><label class="field">Nouveau mot de passe (10 caractères minimum)<input type="password" name="new" required minlength="10" autocomplete="new-password"></label><label class="field">Confirmation<input type="password" name="confirm" required minlength="10" autocomplete="new-password"></label><button class="primary" type="submit">Enregistrer et continuer</button><p class="small muted" style="margin-top:14px">${button('logout-simple','Se déconnecter','subtle')}</p></form>`);
 $('#change-form').addEventListener('submit',async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(d.new!==d.confirm){$('#login-error').textContent='La confirmation ne correspond pas au nouveau mot de passe.';return}let b=e.target.querySelector('button[type=submit]');b.disabled=true;try{await api('password',d);await load();toast('Mot de passe modifié. Bienvenue dans ges-ped.')}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}})
}
start().catch(e=>{$('#app').innerHTML='<div class="loading">'+esc(e.message)+'</div>'});
